// This file is generated by AI.

// 队列优先级按钮 (配音历史与工作台队列共用)。
//
// 只是一个**单图标按钮**, 不做任何文字标注: 箭头指的是"点了会怎样" ——
// 上箭头 = 提升为优先, 下箭头 = 降为常规。已经跑起来或已结束的任务没有可调的顺序,
// 因此这时候不渲染它 (而不是画一个灰按钮)。
//
// 位置固定在「取消」左侧, 于是"这条任务现在能不能被插队"一眼可见。

import { ArrowDownRegular, ArrowUpRegular } from '@fluentui/react-icons';

import type { TaskPriority } from './types';

interface Props {
  priority: TaskPriority;
  onToggle: () => void;
}

export function PriorityButton({ priority, onToggle }: Props) {
  const promote = priority !== 'immediate';
  return (
    <button
      type="button"
      className="priority-button"
      title={promote ? '提升为优先（插到常规队列前面）' : '降为常规'}
      onClick={(event) => {
        event.stopPropagation();
        onToggle();
      }}
    >
      {promote ? <ArrowUpRegular /> : <ArrowDownRegular />}
    </button>
  );
}
